import os
import hashlib
import hmac
import json
import re
from pathlib import PurePosixPath
from urllib.parse import unquote
import unicodedata

# Secure file serving application with role-based access control

SECRET_KEY = os.environ.get("APP_SECRET_KEY", os.urandom(32).hex())
BASE_DIR = "/srv/data"

# Access control list: role -> list of allowed path prefixes
ACL = {
    "admin": ["/srv/data/"],
    "user": ["/srv/data/public/", "/srv/data/shared/"],
    "guest": ["/srv/data/public/"]
}

def generate_session_token(username: str, role: str) -> str:
    """Generate HMAC-signed session token."""
    payload = json.dumps({"user": username, "role": role}, separators=(',', ':'))
    sig = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}.{sig}"

def verify_session(token: str) -> dict:
    """Verify session token and return claims."""
    if not token or '.' not in token:
        return None
    parts = token.rsplit('.', 1)
    if len(parts) != 2:
        return None
    payload_str, signature = parts
    expected_sig = hmac.new(
        SECRET_KEY.encode(), payload_str.encode(), hashlib.sha256
    ).hexdigest()
    if not hmac.compare_digest(signature, expected_sig):
        return None
    try:
        return json.loads(payload_str)
    except (json.JSONDecodeError, ValueError):
        return None

def sanitize_path_component(component: str) -> str:
    """Remove dangerous path components."""
    # Strip null bytes
    component = component.replace('\x00', '')
    # Reject path traversal
    if '..' in component:
        return None
    return component

def normalize_unicode_path(path: str) -> str:
    """Normalize unicode in path to NFC form for consistent filesystem access."""
    return unicodedata.normalize('NFC', path)

def resolve_safe_path(requested_path: str) -> str:
    """Resolve the requested path safely within BASE_DIR."""
    # URL decode
    decoded = unquote(requested_path)
    # Sanitize
    sanitized = sanitize_path_component(decoded)
    if sanitized is None:
        return None
    # Build full path
    full_path = os.path.join(BASE_DIR, sanitized.lstrip('/'))
    # Normalize unicode BEFORE any security checks
    full_path = normalize_unicode_path(full_path)
    # Normalize to remove redundant separators
    full_path = os.path.normpath(full_path)
    # Verify still within BASE_DIR (use trailing separator to prevent
    # sibling-directory prefix bypass, e.g. /srv/data-secret)
    base_with_sep = os.path.join(BASE_DIR, "")
    if full_path != BASE_DIR and not full_path.startswith(base_with_sep):
        return None
    return full_path

def check_acl(role: str, path: str) -> bool:
    """Check if the given role has access to the path."""
    allowed_prefixes = ACL.get(role, [])
    for prefix in allowed_prefixes:
        if path.startswith(prefix):
            return True
    return False

def serve_file(token: str, requested_path: str) -> dict:
    """Main entry point: verify auth, check ACL, serve file."""
    # Step 1: Authenticate
    session = verify_session(token)
    if session is None:
        return {"status": 401, "error": "Authentication failed"}

    role = session.get("role", "guest")
    if role not in ACL:
        return {"status": 403, "error": "Unknown role"}

    # Step 2: Resolve path (includes unicode normalization)
    resolved = resolve_safe_path(requested_path)
    if resolved is None:
        return {"status": 400, "error": "Invalid path"}

    # Step 3: Check ACL against the fully-resolved, normalized path
    if not check_acl(role, resolved):
        return {"status": 403, "error": "Access denied"}

    # Step 4: Read and return file (path already normalized)
    try:
        if not os.path.isfile(resolved):
            return {"status": 404, "error": "Not found"}
        with open(resolved, 'r') as f:
            content = f.read()
        return {"status": 200, "content": content}
    except (IOError, OSError) as e:
        return {"status": 500, "error": "Internal error"}
